// server/routers/workSessions.ts
init_schema2();
init_drizzle_orm();
var workSessionsRouter = router({
  // Get current active/paused session for the user
  current: protectedProcedure.query(async ({ ctx }) => {
    const [session] = await db.select().from(workSessions).where(and(eq(workSessions.userId, ctx.user.id), eq(workSessions.status, "active"))).orderBy(desc(workSessions.startedAt)).limit(1);
    if (session)
      return session;
    const [paused] = await db.select().from(workSessions).where(and(eq(workSessions.userId, ctx.user.id), eq(workSessions.status, "paused"))).orderBy(desc(workSessions.startedAt)).limit(1);
    return paused ?? null;
  }),
  // Start work — only one active session at a time
  start: protectedProcedure.input(external_exports.object({ dailyGoalHours: external_exports.number().min(1).max(24).default(8) })).mutation(async ({ input, ctx }) => {
    const now = /* @__PURE__ */ new Date();
    await db.update(workSessions).set({ status: "ended", endedAt: now, updatedAt: now }).where(and(
      eq(workSessions.userId, ctx.user.id),
      or2(eq(workSessions.status, "active"), eq(workSessions.status, "paused"))
    ));
    const [session] = await db.insert(workSessions).values({
      userId: ctx.user.id,
      dailyGoalHours: input.dailyGoalHours,
      status: "active"
    }).returning();
    return session;
  }),
  // Pause — records when pause started
  pause: protectedProcedure.mutation(async ({ ctx }) => {
    const now = /* @__PURE__ */ new Date();
    const [session] = await db.update(workSessions).set({ status: "paused", pausedAt: now, updatedAt: now }).where(and(eq(workSessions.userId, ctx.user.id), eq(workSessions.status, "active"))).returning();
    return session ?? null;
  }),
  // Resume — adds paused time to total
  resume: protectedProcedure.mutation(async ({ ctx }) => {
    const now = /* @__PURE__ */ new Date();
    const [current] = await db.select().from(workSessions).where(and(eq(workSessions.userId, ctx.user.id), eq(workSessions.status, "paused"))).limit(1);
    if (!current)
      return null;
    const pausedMs = current.pausedAt ? now.getTime() - new Date(current.pausedAt).getTime() : 0;
    const [session] = await db.update(workSessions).set({
      status: "active",
      pausedAt: null,
      totalPausedMs: (current.totalPausedMs ?? 0) + pausedMs,
      updatedAt: now
    }).where(eq(workSessions.id, current.id)).returning();
    return session;
  }),
  // End — finalizes session
  end: protectedProcedure.mutation(async ({ ctx }) => {
    const now = /* @__PURE__ */ new Date();
    const [current] = await db.select().from(workSessions).where(and(
      eq(workSessions.userId, ctx.user.id),
      eq(workSessions.status, "active")
    )).limit(1);
    const [paused] = !current ? await db.select().from(workSessions).where(and(eq(workSessions.userId, ctx.user.id), eq(workSessions.status, "paused"))).limit(1) : [null];
    const target = current ?? paused;
    if (!target)
      return null;
    const extraPausedMs = target.pausedAt ? now.getTime() - new Date(target.pausedAt).getTime() : 0;
    const [session] = await db.update(workSessions).set({
      status: "ended",
      endedAt: now,
      totalPausedMs: (target.totalPausedMs ?? 0) + extraPausedMs,
      updatedAt: now
    }).where(eq(workSessions.id, target.id)).returning();
    return session;
  }),
  // History — last 30 sessions for this user
  history: protectedProcedure.query(async ({ ctx }) => {
    return db.select().from(workSessions).where(eq(workSessions.userId, ctx.user.id)).orderBy(desc(workSessions.startedAt)).limit(30);
  }),
  // Admin: all seller sessions today + recent task activity + last-online history
  allActiveToday: adminProcedure.query(async () => {
    const now = /* @__PURE__ */ new Date();
    const todayStart = spMidnight(now);
    const thirtyDaysAgo = new Date(now.getTime() - 30 * 864e5);
    const twoHoursAgo = new Date(now.getTime() - 2 * 60 * 60 * 1e3);
    const [allSellers, todaySessions, todayTasks, allRecentSessions, ghostCounts, burstTasks] = await Promise.all([
      db.select().from(sellers).where(eq(sellers.status, "active")),
      // Include active AND paused sessions — paused attendant must still appear on admin view
      db.select().from(workSessions).where(and(gte(workSessions.startedAt, todayStart), or2(eq(workSessions.status, "active"), eq(workSessions.status, "paused")))).orderBy(desc(workSessions.startedAt)),
      // Today's edited tasks — include title so we can show what they worked on
      db.select({
        userId: tasks.userId,
        assignedTo: tasks.assignedTo,
        title: tasks.title,
        lastContactedAt: tasks.lastContactedAt
      }).from(tasks).where(gte(tasks.lastContactedAt, todayStart)).orderBy(desc(tasks.lastContactedAt)),
      // Most recent session per seller in the last 90 days — for "last online" info
      db.select({
        userId: workSessions.userId,
        startedAt: workSessions.startedAt,
        endedAt: workSessions.endedAt,
        status: workSessions.status
      }).from(workSessions).where(gte(workSessions.startedAt, new Date(Date.now() - 90 * 864e5))).orderBy(desc(workSessions.startedAt)).limit(200),
      // Ghost count: tasks not contacted in 30+ days (aggregated, no row scan)
      db.select({
        userId: tasks.userId,
        assignedTo: tasks.assignedTo,
        ghostCount: count()
      }).from(tasks).where(or2(isNull2(tasks.lastContactedAt), lt(tasks.lastContactedAt, thirtyDaysAgo))).groupBy(tasks.userId, tasks.assignedTo),
      // Burst detection: only tasks contacted in last 2 hours (not all tasks)
      db.select({
        userId: tasks.userId,
        assignedTo: tasks.assignedTo,
        lastContactedAt: tasks.lastContactedAt
      }).from(tasks).where(and(isNotNull(tasks.lastContactedAt), gte(tasks.lastContactedAt, twoHoursAgo)))
    ]);
    return allSellers.map((seller) => {
      const session = todaySessions.find((s4) => s4.userId === seller.userId) ?? null;
      const mine = todayTasks.filter(
        (t5) => t5.userId === seller.userId || t5.assignedTo === seller.name
      );
      const contactsToday = mine.length;
      const lastActivityDate = mine.length > 0 ? new Date(Math.max(...mine.map((t5) => new Date(t5.lastContactedAt).getTime()))) : null;
      const recentTasks = mine.slice(0, 5).map((t5) => ({
        title: t5.title.split(" - ")[0].slice(0, 60),
        lastContactedAt: t5.lastContactedAt
      }));
      const lastOnlineSession = !session ? allRecentSessions.find((s4) => s4.userId === seller.userId) ?? null : null;
      const lastOnlineAt = lastOnlineSession ? lastOnlineSession.endedAt ?? lastOnlineSession.startedAt : null;
      let workedMs = 0;
      let idleSinceMs = 0;
      if (session) {
        const end2 = session.endedAt ? new Date(session.endedAt) : now;
        const elapsed = end2.getTime() - new Date(session.startedAt).getTime();
        let pausedTotal = session.totalPausedMs ?? 0;
        if (session.status === "paused" && session.pausedAt) {
          pausedTotal += now.getTime() - new Date(session.pausedAt).getTime();
        }
        workedMs = Math.max(0, elapsed - pausedTotal);
        if (session.status === "active" && lastActivityDate) {
          idleSinceMs = now.getTime() - lastActivityDate.getTime();
        } else if (session.status === "active" && contactsToday === 0) {
          idleSinceMs = now.getTime() - new Date(session.startedAt).getTime();
        }
      }
      const ghostCount = ghostCounts.filter((g4) => g4.userId === seller.userId || g4.assignedTo === seller.name).reduce((sum2, g4) => sum2 + Number(g4.ghostCount), 0);
      const sellerBurst = burstTasks.filter((t5) => t5.userId === seller.userId || t5.assignedTo === seller.name).filter((t5) => t5.lastContactedAt).sort((a5, b3) => new Date(a5.lastContactedAt).getTime() - new Date(b3.lastContactedAt).getTime());
      let burstMax = 0;
      for (let i4 = 0; i4 < sellerBurst.length; i4++) {
        const base = new Date(sellerBurst[i4].lastContactedAt).getTime();
        const inWin = sellerBurst.filter((t5) => {
          const d3 = new Date(t5.lastContactedAt).getTime() - base;
          return d3 >= 0 && d3 <= 6e5;
        }).length;
        if (inWin > burstMax)
          burstMax = inWin;
      }
      return {
        sellerId: seller.id,
        name: seller.name,
        email: seller.email,
        session: session ? {
          startedAt: session.startedAt,
          status: session.status,
          pausedAt: session.pausedAt ?? null,
          workedMs
        } : null,
        contactsToday,
        lastActivityDate,
        idleSinceMs,
        recentTasks,
        lastOnlineAt,
        ghostCount,
        burstAlert: burstMax >= 5,
        burstMax
      };
    });
  })
});

