  // ── Inscrição manual de leads ────────────────────────────────────────────
  enrollTasksInSequence: protectedProcedure.input(external_exports.object({ sequenceId: external_exports.number(), taskIds: external_exports.array(external_exports.number()).min(1) })).mutation(async ({ input, ctx }) => {
    if (ctx.user.role !== "admin" && ctx.user.role !== "manager") {
      const [seller] = await db.select({ emk: sellers.emailMarketingEnabled }).from(sellers).where(eq(sellers.userId, ctx.user.id)).limit(1);
      if (!seller?.emk)
        throw new TRPCError({ code: "FORBIDDEN", message: "Voc\xEA n\xE3o tem permiss\xE3o para Email Marketing" });
    }
    const [sequence] = await db.select().from(emailSequences).where(eq(emailSequences.id, input.sequenceId));
    if (!sequence)
      throw new TRPCError({ code: "NOT_FOUND", message: "Sequ\xEAncia n\xE3o encontrada" });
    const sellerRows = await db.select({ name: sellers.name, email: sellers.email }).from(sellers);
    const sellerMap = new Map(sellerRows.map((s4) => [s4.name.toLowerCase(), s4.email]));
    const taskRows = await db.select({ id: tasks.id, email: tasks.email, title: tasks.title, assignedTo: tasks.assignedTo, emailConfirmed: tasks.emailConfirmed }).from(tasks).where(inArray(tasks.id, input.taskIds));
    let enrolled = 0;
    let skippedNoEmail = 0;
    let skippedUnconfirmed = 0;
    let skippedDuplicateOrSuppressed = 0;
    const skipReasons = [];
    for (const t5 of taskRows) {
      if (!t5.email) {
        skippedNoEmail++;
        skipReasons.push(`${firstPart2(t5.title)}: sem email`);
        continue;
      }
      if (!t5.emailConfirmed) {
        skippedUnconfirmed++;
        skipReasons.push(`${t5.email}: n\xE3o confirmado`);
        continue;
      }
      const result = await enrollInSequence(input.sequenceId, {
        email: t5.email,
        name: firstPart2(t5.title),
        replyTo: t5.assignedTo ? sellerMap.get(t5.assignedTo.toLowerCase()) : void 0,
        taskId: t5.id
      });
      if (result.enrolled)
        enrolled++;
      else {
        skippedDuplicateOrSuppressed++;
        skipReasons.push(`${t5.email}: ${result.reason ?? "duplicado/suprimido"}`);
      }
    }
    console.log(`[enrollTasksInSequence] seq=${input.sequenceId}: enrolled=${enrolled}, skipped=${skippedNoEmail + skippedUnconfirmed + skippedDuplicateOrSuppressed}`, skipReasons.length > 0 ? skipReasons : "");
    return { enrolled, skippedNoEmail, skippedUnconfirmed, skippedDuplicateOrSuppressed, skipReasons };
  }),
