// server/routers/catalog.ts
init_drizzle_orm();
init_schema2();
var MAX_FILE_BYTES = 2.5 * 1024 * 1024;
var ownerType = external_exports.enum(["product", "company"]);
function dataUrlBytes(dataUrl) {
  const comma = dataUrl.indexOf(",");
  const b64 = comma >= 0 ? dataUrl.slice(comma + 1) : dataUrl;
  const padding = b64.endsWith("==") ? 2 : b64.endsWith("=") ? 1 : 0;
  return Math.floor(b64.length * 3 / 4) - padding;
}
function assertDataUrl(value2, label) {
  if (!value2.startsWith("data:")) {
    throw new TRPCError({ code: "BAD_REQUEST", message: `${label} inv\xE1lido.` });
  }
  if (dataUrlBytes(value2) > MAX_FILE_BYTES) {
    throw new TRPCError({
      code: "PAYLOAD_TOO_LARGE",
      message: `${label} excede 2,5 MB. Comprima o arquivo e tente de novo.`
    });
  }
}
var catalogRouter = router({
  /**
   * Metadados de todos os anexos + as fotos personalizadas. Sem `content`:
   * trazer o base64 de todos os anexos aqui faria a página baixar megabytes a
   * cada abertura.
   */
  list: protectedProcedure.query(async () => {
    const docs = await db.select({
      id: catalogDocuments.id,
      ownerType: catalogDocuments.ownerType,
      ownerId: catalogDocuments.ownerId,
      title: catalogDocuments.title,
      fileName: catalogDocuments.fileName,
      fileType: catalogDocuments.fileType,
      fileSize: catalogDocuments.fileSize,
      uploadedByName: catalogDocuments.uploadedByName,
      createdAt: catalogDocuments.createdAt
    }).from(catalogDocuments).orderBy(desc(catalogDocuments.createdAt));
    const images = await db.select({ ownerId: catalogImages.ownerId, imageUrl: catalogImages.imageUrl }).from(catalogImages);
    const specs = await db.select().from(catalogSpecs);
    return { documents: docs, images, specs };
  }),
  /** Binário de um anexo, buscado só quando o usuário baixa ou visualiza. */
  getContent: protectedProcedure.input(external_exports.object({ id: external_exports.number() })).query(async ({ input }) => {
    const [doc] = await db.select({
      content: catalogDocuments.content,
      fileName: catalogDocuments.fileName,
      title: catalogDocuments.title
    }).from(catalogDocuments).where(eq(catalogDocuments.id, input.id));
    if (!doc)
      throw new TRPCError({ code: "NOT_FOUND", message: "Documento n\xE3o encontrado." });
    return doc;
  }),
  /** Anexa um arquivo a um produto ou card da empresa. */
  addDocument: staffProcedure.input(
    external_exports.object({
      ownerType,
      ownerId: external_exports.string().min(1).max(120),
      title: external_exports.string().min(1).max(200),
      fileName: external_exports.string().max(260).optional(),
      fileType: external_exports.string().max(30).default("PDF"),
      fileSize: external_exports.string().max(40).optional(),
      content: external_exports.string().min(1)
    })
  ).mutation(async ({ input, ctx }) => {
    assertDataUrl(input.content, "Arquivo");
    const [created] = await db.insert(catalogDocuments).values({
      ownerType: input.ownerType,
      ownerId: input.ownerId,
      title: input.title.trim(),
      fileName: input.fileName ?? null,
      fileType: input.fileType,
      fileSize: input.fileSize ?? null,
      content: input.content,
      uploadedByUserId: ctx.user.id,
      uploadedByName: ctx.user.name ?? null
    }).returning({ id: catalogDocuments.id });
    return created;
  }),
  deleteDocument: staffProcedure.input(external_exports.object({ id: external_exports.number() })).mutation(async ({ input }) => {
    const deleted = await db.delete(catalogDocuments).where(eq(catalogDocuments.id, input.id)).returning({ id: catalogDocuments.id });
    if (deleted.length === 0) {
      throw new TRPCError({ code: "NOT_FOUND", message: "Documento n\xE3o encontrado." });
    }
    return { ok: true };
  }),
  /**
   * Grava as especificações técnicas reais de um produto. Campo vazio é
   * gravado como null e a ficha mostra "não informado" — nunca um valor
   * inventado, já que isto vai no material enviado ao cliente.
   */
  setSpecs: staffProcedure.input(
    external_exports.object({
      ownerId: external_exports.string().min(1).max(120),
      weight: external_exports.string().max(200).optional(),
      granulometry: external_exports.string().max(200).optional(),
      solubility: external_exports.string().max(200).optional(),
      purity: external_exports.string().max(200).optional(),
      storage: external_exports.string().max(300).optional()
    })
  ).mutation(async ({ input, ctx }) => {
    const clean4 = (v4) => {
      const t5 = (v4 ?? "").trim();
      return t5.length > 0 ? t5 : null;
    };
    const values = {
      weight: clean4(input.weight),
      granulometry: clean4(input.granulometry),
      solubility: clean4(input.solubility),
      purity: clean4(input.purity),
      storage: clean4(input.storage),
      updatedByUserId: ctx.user.id,
      updatedByName: ctx.user.name ?? null,
      updatedAt: /* @__PURE__ */ new Date()
    };
    await db.insert(catalogSpecs).values({ ownerId: input.ownerId, ...values }).onConflictDoUpdate({ target: catalogSpecs.ownerId, set: values });
    return { ok: true };
  }),
  /** Define (ou troca) a foto de um produto. Uma linha por produto. */
  setImage: staffProcedure.input(external_exports.object({ ownerId: external_exports.string().min(1).max(120), imageUrl: external_exports.string().min(1) })).mutation(async ({ input, ctx }) => {
    assertDataUrl(input.imageUrl, "Imagem");
    await db.insert(catalogImages).values({
      ownerId: input.ownerId,
      imageUrl: input.imageUrl,
      updatedByUserId: ctx.user.id,
      updatedAt: /* @__PURE__ */ new Date()
    }).onConflictDoUpdate({
      target: catalogImages.ownerId,
      set: { imageUrl: input.imageUrl, updatedByUserId: ctx.user.id, updatedAt: /* @__PURE__ */ new Date() }
    });
    return { ok: true };
  }),
  /** Remove a foto personalizada, voltando à ilustração padrão do card. */
  resetImage: staffProcedure.input(external_exports.object({ ownerId: external_exports.string().min(1).max(120) })).mutation(async ({ input }) => {
    await db.delete(catalogImages).where(eq(catalogImages.ownerId, input.ownerId));
    return { ok: true };
  }),
  /**
   * Importa o que já estava no IndexedDB do navegador de quem abriu a página,
   * para que os arquivos subidos antes desta correção não se percam. Idempotente
   * por (ownerType, ownerId, title): reexecutar não duplica.
   */
  migrateFromLocal: staffProcedure.input(
    external_exports.object({
      documents: external_exports.array(
        external_exports.object({
          ownerType,
          ownerId: external_exports.string().min(1).max(120),
          title: external_exports.string().min(1).max(200),
          fileName: external_exports.string().max(260).optional(),
          fileType: external_exports.string().max(30).default("PDF"),
          fileSize: external_exports.string().max(40).optional(),
          content: external_exports.string().min(1)
        })
      ).max(100),
      images: external_exports.array(external_exports.object({ ownerId: external_exports.string().min(1).max(120), imageUrl: external_exports.string().min(1) })).max(60)
    })
  ).mutation(async ({ input, ctx }) => {
    let docsImported = 0;
    let imagesImported = 0;
    for (const d3 of input.documents) {
      if (!d3.content.startsWith("data:") || dataUrlBytes(d3.content) > MAX_FILE_BYTES)
        continue;
      const [dup] = await db.select({ id: catalogDocuments.id }).from(catalogDocuments).where(
        and(
          eq(catalogDocuments.ownerType, d3.ownerType),
          eq(catalogDocuments.ownerId, d3.ownerId),
          eq(catalogDocuments.title, d3.title.trim())
        )
      ).limit(1);
      if (dup)
        continue;
      await db.insert(catalogDocuments).values({
        ownerType: d3.ownerType,
        ownerId: d3.ownerId,
        title: d3.title.trim(),
        fileName: d3.fileName ?? null,
        fileType: d3.fileType,
        fileSize: d3.fileSize ?? null,
        content: d3.content,
        uploadedByUserId: ctx.user.id,
        uploadedByName: ctx.user.name ?? null
      });
      docsImported++;
    }
    for (const img of input.images) {
      if (!img.imageUrl.startsWith("data:") || dataUrlBytes(img.imageUrl) > MAX_FILE_BYTES)
        continue;
      const [existing] = await db.select({ ownerId: catalogImages.ownerId }).from(catalogImages).where(eq(catalogImages.ownerId, img.ownerId)).limit(1);
      if (existing)
        continue;
      await db.insert(catalogImages).values({
        ownerId: img.ownerId,
        imageUrl: img.imageUrl,
        updatedByUserId: ctx.user.id
      });
      imagesImported++;
    }
    return { docsImported, imagesImported };
  })
});

